<?php
namespace ExcelHerbal\ERP7\Communication;

use ExcelHerbal\ERP7\Core\Input;
use ExcelHerbal\ERP7\Database\Db;
use ExcelHerbal\ERP7\Database\Transaction;
use ExcelHerbal\ERP7\Domain\DomainException;
use ExcelHerbal\ERP7\Security\Actor;
use ExcelHerbal\ERP7\Security\Audit;
use ExcelHerbal\ERP7\Security\Capabilities;
use ExcelHerbal\ERP7\Security\Guard;

final class CommunicationAdminService {
    public static function tasks(Actor $a,?int $branchId,string $status,int $limit,int $offset):array {Guard::cap($a,Capabilities::COMM_MANAGE);[$limit,$offset]=self::page($limit,$offset);$status=strtolower(trim($status))?:'open';if(!in_array($status,['open','completed','all'],true))throw new DomainException('Task status is invalid.','task_status_invalid',422);$ids=self::scope($a,$branchId,Capabilities::COMM_MANAGE);$where=$status==='all'?'1=1':"t.status='".esc_sql($status)."'";$db=Db::wpdb();$sql="SELECT t.*,e.employee_code,e.full_name AS assigned_employee_name FROM ".Db::table('tasks')." t LEFT JOIN ".Db::table('employees')." e ON e.id=t.assigned_employee_id AND e.company_id=t.company_id WHERE t.company_id=%d AND t.branch_id IN (".implode(',',array_map('intval',$ids)).") AND {$where} ORDER BY CASE WHEN t.status='open' THEN 0 ELSE 1 END,t.due_at IS NULL,t.due_at,t.id DESC LIMIT %d OFFSET %d";return (array)$db->get_results($db->prepare($sql,$a->companyId,$limit,$offset),ARRAY_A);}
    public static function announcements(Actor $a,?int $branchId,string $status,int $limit,int $offset):array {Guard::cap($a,Capabilities::COMM_MANAGE);[$limit,$offset]=self::page($limit,$offset);$status=strtolower(trim($status))?:'all';if(!in_array($status,['published','expired','all'],true))throw new DomainException('Announcement status is invalid.','announcement_status_invalid',422);$ids=self::scope($a,$branchId,Capabilities::COMM_MANAGE);$db=Db::wpdb();$branch="(a.branch_id IS NULL OR a.branch_id IN (".implode(',',array_map('intval',$ids))."))";$where=$status==='all'?'1=1':$db->prepare('a.status=%s',$status);$sql="SELECT a.*,(SELECT COUNT(*) FROM ".Db::table('announcement_acknowledgements')." aa WHERE aa.company_id=a.company_id AND aa.announcement_id=a.id) AS acknowledgement_count FROM ".Db::table('announcements')." a WHERE a.company_id=%d AND {$branch} AND {$where} ORDER BY a.id DESC LIMIT %d OFFSET %d";return (array)$db->get_results($db->prepare($sql,$a->companyId,$limit,$offset),ARRAY_A);}
    public static function createAnnouncement(Actor $a,array $data):array {Guard::cap($a,Capabilities::COMM_MANAGE);$branch=self::optionalBranch($a,$data['branch_id']??null,Capabilities::COMM_MANAGE);$title=trim((string)($data['title']??''));$body=trim((string)($data['body']??''));$expires=trim((string)($data['expires_at']??''));$expires=$expires===''?null:Input::utcDateTime($expires,'Announcement expires_at');if($title===''||$body===''||strlen($title)>190||strlen($body)>10000)throw new DomainException('Announcement title/body is invalid.','announcement_invalid',422);if($expires!==null&&$expires<=Db::now())throw new DomainException('Announcement expiry must be in the future.','announcement_expiry_invalid',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('announcements'),['company_id'=>$a->companyId,'branch_id'=>$branch,'title'=>$title,'body'=>$body,'status'=>'published','published_by'=>$a->employeeId,'published_at'=>Db::now(),'expires_at'=>$expires]);$id=(int)$db->insert_id;Audit::add($a,'announcement.create','announcement',$id,['branch_id'=>$branch]);return ['id'=>$id,'status'=>'published','branch_id'=>$branch,'expires_at'=>$expires];}
    public static function expireAnnouncement(Actor $a,int $id):array {Guard::cap($a,Capabilities::COMM_MANAGE);return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('announcements');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Announcement not found.','announcement_not_found',404);if((int)($r['branch_id']??0)>0)Guard::branch($a,(int)$r['branch_id'],Capabilities::COMM_MANAGE);Db::mustUpdate($db,$t,['status'=>'expired','expires_at'=>Db::now()],['id'=>$id]);Audit::add($a,'announcement.expire','announcement',$id,[]);return ['id'=>$id,'status'=>'expired'];});}
    public static function createNotification(Actor $a,array $data):array {Guard::cap($a,Capabilities::COMM_MANAGE);$employeeId=(int)($data['employee_id']??0);$e=self::employee($a,$employeeId);$type=trim((string)($data['type']??'general'))?:'general';$title=trim((string)($data['title']??''));$body=trim((string)($data['body']??''));$entityType=trim((string)($data['entity_type']??''))?:null;$entityId=(int)($data['entity_id']??0);if($title===''||strlen($title)>190||strlen($type)>60||strlen($body)>5000||($entityType!==null&&strlen($entityType)>60))throw new DomainException('Notification data is invalid.','notification_invalid',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('notifications'),['company_id'=>$a->companyId,'employee_id'=>$employeeId,'type'=>$type,'title'=>$title,'body'=>$body?:null,'entity_type'=>$entityType,'entity_id'=>$entityId>0?$entityId:null,'read_at'=>null,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'notification.create','notification',$id,['employee_id'=>$employeeId,'branch_id'=>(int)$e['assigned_branch_id']]);return ['id'=>$id,'employee_id'=>$employeeId,'created'=>true];}
    public static function pushDevices(Actor $a):array {Guard::cap($a,Capabilities::COMM_VIEW);$db=Db::wpdb();return (array)$db->get_results($db->prepare("SELECT id,platform,device_name,active,last_seen_at,created_at,updated_at FROM ".Db::table('push_devices')." WHERE company_id=%d AND employee_id=%d ORDER BY active DESC,last_seen_at DESC,id DESC",$a->companyId,$a->employeeId),ARRAY_A);}
    private static function employee(Actor $a,int $employeeId):array {if($employeeId<1)throw new DomainException('employee_id is required.','parameter_required',422);$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active'",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);Guard::branch($a,(int)$e['assigned_branch_id'],Capabilities::COMM_MANAGE);return $e;}
    private static function optionalBranch(Actor $a,mixed $raw,string $cap):?int {$id=($raw===null||$raw==='')?null:(int)$raw;if($id!==null){if($id<1)throw new DomainException('branch_id must be positive or omitted.','parameter_invalid',422);Guard::branch($a,$id,$cap);return$id;}if($a->can(Capabilities::ACCESS_MANAGE))return null;$db=Db::wpdb();$total=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('branches')." WHERE company_id=%d AND status='active'",$a->companyId));$owned=count(array_unique(array_filter(array_map('intval',$a->branchIds),fn($v)=>$v>0)));if($total<1||$owned<$total)throw new DomainException('Company-wide announcement requires authority over all active branches.','company_scope_forbidden',403);return null;}
    private static function scope(Actor $a,?int $branchId,string $cap):array {if($branchId){Guard::branch($a,$branchId,$cap);return[$branchId];}$ids=array_values(array_unique(array_filter(array_map('intval',$a->branchIds),fn($v)=>$v>0)));if(!$ids)throw new DomainException('No authorised branch scope.','branch_scope_empty',403);return$ids;}
    private static function page(int $limit,int $offset):array{return[max(1,min(200,$limit?:100)),max(0,$offset)];}
}
